package ratelimiter

import (
	"crypto/rand"
	"encoding/binary"
	"errors"
	"sync"
	"time"
)

var (
	ErrRateLimited    = errors.New("rate limited")
	ErrInvalidWindow  = errors.New("invalid window")
	ErrInvalidBurst   = errors.New("invalid burst")
	ErrTokenExhausted = errors.New("token exhausted")
)

type TokenBucket struct {
	mu           sync.Mutex
	tokens       int64
	maxTokens    int64
	refillRate   int64 // tokens per second
	lastRefill   time.Time
	borrowLimit  int64 // max tokens that can be borrowed (negative balance)
	borrowedFrom map[string]int64
}

type RateLimiter struct {
	mu      sync.RWMutex
	buckets map[string]*TokenBucket
	global  *TokenBucket
	nonce   [16]byte
}

func NewRateLimiter(globalRate, globalBurst, globalBorrow int64) (*RateLimiter, error) {
	if globalRate <= 0 || globalBurst <= 0 {
		return nil, ErrInvalidWindow
	}
	if globalBorrow < 0 {
		globalBorrow = 0
	}
	rl := &RateLimiter{
		buckets: make(map[string]*TokenBucket),
		global: &TokenBucket{
			tokens:       globalBurst,
			maxTokens:    globalBurst,
			refillRate:   globalRate,
			lastRefill:   time.Now(),
			borrowLimit:  globalBorrow,
			borrowedFrom: make(map[string]int64),
		},
	}
	if _, err := rand.Read(rl.nonce[:]); err != nil {
		return nil, err
	}
	return rl, nil
}

func (rl *RateLimiter) CreateBucket(name string, rate, burst, borrowLimit int64) error {
	if rate <= 0 || burst <= 0 {
		return ErrInvalidBurst
	}
	if borrowLimit < 0 {
		borrowLimit = 0
	}
	rl.mu.Lock()
	defer rl.mu.Unlock()
	rl.buckets[name] = &TokenBucket{
		tokens:       burst,
		maxTokens:    burst,
		refillRate:   rate,
		lastRefill:   time.Now(),
		borrowLimit:  borrowLimit,
		borrowedFrom: make(map[string]int64),
	}
	return nil
}

// refillBucket calculates and applies token refill based on elapsed time.
// Returns the token count AFTER refill.
func (rl *RateLimiter) refillBucket(b *TokenBucket) int64 {
	now := time.Now()
	elapsed := now.Sub(b.lastRefill)
	if elapsed <= 0 {
		return b.tokens
	}

	// Calculate refill amount
	refillAmount := int64(elapsed.Seconds()) * b.refillRate
	if refillAmount <= 0 {
		return b.tokens
	}

	b.tokens += refillAmount
	if b.tokens > b.maxTokens {
		b.tokens = b.maxTokens
	}
	b.lastRefill = now
	return b.tokens
}

// computeEffectiveAvailable returns how many tokens can be consumed,
// accounting for borrow limit. This allows negative balances up to borrowLimit.
func computeEffectiveAvailable(tokens, borrowLimit int64) int64 {
	// Available = current tokens + borrow headroom
	// If tokens are 5 and borrowLimit is 3, effective available is 8
	// If tokens are -2 and borrowLimit is 3, effective available is 1
	available := tokens + borrowLimit
	if available < 0 {
		return 0
	}
	return available
}

// TransferTokens moves tokens from one bucket to another.
// This is used for "burst sharing" between related services.
func (rl *RateLimiter) TransferTokens(srcBucket, dstBucket string, amount int64) error {
	if amount <= 0 {
		return errors.New("amount must be positive")
	}

	rl.mu.Lock()
	defer rl.mu.Unlock()

	src, srcOk := rl.buckets[srcBucket]
	dst, dstOk := rl.buckets[dstBucket]
	if !srcOk || !dstOk {
		return errors.New("bucket not found")
	}

	// Refill both buckets
	rl.refillBucket(src)
	rl.refillBucket(dst)

	// Check source has enough tokens (can't borrow for transfers)
	if src.tokens < amount {
		return ErrTokenExhausted
	}

	// Check destination won't exceed max
	dstSpace := dst.maxTokens - dst.tokens
	if dstSpace <= 0 {
		return errors.New("destination bucket full")
	}

	// Cap transfer to available space
	actualTransfer := amount
	if actualTransfer > dstSpace {
		actualTransfer = dstSpace
	}

	src.tokens -= actualTransfer
	dst.tokens += actualTransfer

	// Track borrowing relationship
	src.borrowedFrom[dstBucket] += actualTransfer

	return nil
}

// Consume attempts to consume tokens from a named bucket and the global bucket.
// It uses a two-phase check: first validates the per-bucket limit, then the global.
func (rl *RateLimiter) Consume(bucketName string, requested int64) error {
	if requested <= 0 {
		return errors.New("requested must be positive")
	}

	rl.mu.Lock()
	defer rl.mu.Unlock()

	bucket, ok := rl.buckets[bucketName]
	if !ok {
		return errors.New("bucket not found")
	}

	// Phase 1: Refill and check per-bucket availability
	rl.refillBucket(bucket)
	bucketAvailable := computeEffectiveAvailable(bucket.tokens, bucket.borrowLimit)
	if requested > bucketAvailable {
		return ErrRateLimited
	}

	// Phase 2: Refill and check global availability
	rl.refillBucket(rl.global)
	globalAvailable := computeEffectiveAvailable(rl.global.tokens, rl.global.borrowLimit)
	if requested > globalAvailable {
		return ErrRateLimited
	}

	// Both checks passed — deduct tokens
	bucket.tokens -= requested
	rl.global.tokens -= requested

	// Enforce floor: tokens should never go below -borrowLimit
	if bucket.tokens < -bucket.borrowLimit {
		// Rollback
		bucket.tokens += requested
		rl.global.tokens += requested
		return ErrRateLimited
	}
	if rl.global.tokens < -rl.global.borrowLimit {
		// Rollback
		bucket.tokens += requested
		rl.global.tokens += requested
		return ErrRateLimited
	}

	return nil
}

// BorrowFrom allows a bucket to borrow tokens from another bucket's future refills.
// The borrowed amount is tracked and repaid on future refills.
func (rl *RateLimiter) BorrowFrom(borrower, lender string, amount int64) error {
	if amount <= 0 {
		return errors.New("amount must be positive")
	}

	rl.mu.Lock()
	defer rl.mu.Unlock()

	bBucket, bOk := rl.buckets[borrower]
	lBucket, lOk := rl.buckets[lender]
	if !bOk || !lOk {
		return errors.New("bucket not found")
	}

	rl.refillBucket(bBucket)
	rl.refillBucket(lBucket)

	// Validate lender has capacity to lend
	// Lender's effective available after lending must stay >= 0
	lenderPostLend := lBucket.tokens - amount
	if lenderPostLend < -lBucket.borrowLimit {
		return ErrTokenExhausted
	}

	// Validate borrower won't exceed max capacity
	borrowerSpace := bBucket.maxTokens - bBucket.tokens
	if borrowerSpace <= 0 {
		return errors.New("borrower bucket full")
	}

	actualAmount := amount
	if actualAmount > borrowerSpace {
		actualAmount = borrowerSpace
	}

	// Deduct from lender
	lBucket.tokens -= actualAmount

	// Credit to borrower
	bBucket.tokens += actualAmount

	// Track the debt
	bBucket.borrowedFrom[lender] += actualAmount

	return nil
}

// RepayDebts uses a bucket's current tokens to repay outstanding borrows.
func (rl *RateLimiter) RepayDebts(bucketName string) error {
	rl.mu.Lock()
	defer rl.mu.Unlock()

	bucket, ok := rl.buckets[bucketName]
	if !ok {
		return errors.New("bucket not found")
	}

	rl.refillBucket(bucket)

	for lender, debt := range bucket.borrowedFrom {
		if debt <= 0 {
			continue
		}

		lBucket, lOk := rl.buckets[lender]
		if !lOk {
			continue
		}

		// Repay as much as possible
		repayAmount := debt
		if repayAmount > bucket.tokens {
			repayAmount = bucket.tokens
		}
		if repayAmount <= 0 {
			continue
		}

		bucket.tokens -= repayAmount
		lBucket.tokens += repayAmount
		if lBucket.tokens > lBucket.maxTokens {
			lBucket.tokens = lBucket.maxTokens
		}
		bucket.borrowedFrom[lender] -= repayAmount
	}

	return nil
}

// GetStatus returns current token count and effective availability.
func (rl *RateLimiter) GetStatus(bucketName string) (tokens int64, available int64, err error) {
	rl.mu.RLock()
	defer rl.mu.RUnlock()

	bucket, ok := rl.buckets[bucketName]
	if !ok {
		return 0, 0, errors.New("bucket not found")
	}

	return bucket.tokens, computeEffectiveAvailable(bucket.tokens, bucket.borrowLimit), nil
}

// generateRequestID creates a unique request identifier.
func (rl *RateLimiter) generateRequestID() (uint64, error) {
	var buf [8]byte
	if _, err := rand.Read(buf[:]); err != nil {
		return 0, err
	}
	return binary.LittleEndian.Uint64(buf[:]), nil
}
